"use strict"
// eslint-disable-next-line no-console
// eslint-disable-next-line prefer-rest-params

module.exports.deprecate = (fn, msg) => {
  let once = true
  return function deprecate() {
    if (once) {
      console.warn(`DeprecationWarning: ${msg}`)
      once = false
    }
    return fn.apply(this, arguments)
  }
}
